  SELECT * INTO STRICT nav FROM public.navision_backend_records b WHERE b.source_system='microsoft_navision' AND b.is_current AND b.record_status='current' AND public.normalize_vehicle_stock_number(coalesce(b.normalized_data->>'batch',b.normalized_data->>'stock'))=item->>'stock' FOR UPDATE;
