  vid:=extensions.uuid_generate_v5('b58b5f75-d004-5a76-b9aa-48c801b4ad7d'::uuid,(item->>'stock')||':'||(item->>'vin')||':'||(item->>'source_hash'));
  INSERT INTO public.vehicles(id,permanent_vehicle_id,stock_number,vin,job_card_number,customer_name,vehicle_description,model,lifecycle_state,visible_on_board,current_location,source_system,source_batch_id,source_record_id,source_payload,created_by,updated_by) VALUES(vid,'PDC-AI-'||upper(substr(item->>'source_hash',1,24)),item->>'stock',item->>'vin',item->>'job_card',coalesce(nav.normalized_data->>'client',item->>'customer'),coalesce(nav.normalized_data->>'modelDescription',item->>'vehicle_description'),coalesce(nav.normalized_data->>'modelDescription',item->>'vehicle_description'),'active',true,CASE upper(coalesce(nav.normalized_data->>'navisionLocationStatus','')) WHEN 'YH' THEN 'Yard Hold' WHEN 'IT' THEN 'IT' ELSE 'PMB' END,'microsoft_navision',nav.dealer_code,nav.id::text,jsonb_build_object('authority','exact-email-uid639-640-501','provider_uid','1:'||(item->>'uid'),'source_hash',item->>'source_hash','attachment_hash',item->>'attachment_hash','backend_record_id',nav.id), '69846ef4-a74c-4569-9e35-376cf0837888','69846ef4-a74c-4569-9e35-376cf0837888') RETURNING * INTO v;
  UPDATE public.navision_backend_records SET canonical_vehicle_id=vid WHERE id=nav.id;INSERT INTO public.navision_board_activations(backend_record_id,canonical_vehicle_id,activated_stock_number,active,activated_by,activation_source) VALUES(nav.id,vid,item->>'stock',true,'69846ef4-a74c-4569-9e35-376cf0837888','approved_email_build') ON CONFLICT(backend_record_id) DO UPDATE SET canonical_vehicle_id=excluded.canonical_vehicle_id,activated_stock_number=excluded.activated_stock_number,active=true,completed_at=null,activated_by=excluded.activated_by,activation_source=excluded.activation_source;
  PERFORM public.pdc_refresh_linked_vehicle_from_navision_481(nav.id,'69846ef4-a74c-4569-9e35-376cf0837888','pmbcontroller@gmail.com');
