  INSERT INTO public.pdc_authenticated_email_import_receipts(actor_id,idempotency_key,request_hash,source_hash,evidence_hash,source_uid,sender_address,source_received_at,stock_number,vin,backend_record_id,backend_record_version,vehicle_id,identity_source,required_work,response) VALUES('69846ef4-a74c-4569-9e35-376cf0837888','pdc-email-import-'||substr(item->>'source_hash',1,40),encode(extensions.digest(convert_to(item::text,'UTF8'),'sha256'),'hex'),item->>'source_hash',item->>'attachment_hash','1:'||(item->>'uid'),'craig.watson@broometoyota.com.au',(item->>'received_at')::timestamptz,item->>'stock',item->>'vin',nav.id,nav.version,vid,'navision_exact',req,response) RETURNING * INTO rec;
