   IF k<>'owner_supplied_document' THEN INSERT INTO public.vehicle_work_items(vehicle_id,work_key,required,completed,updated_at) VALUES(vid,k,true,false,clock_timestamp()) ON CONFLICT(vehicle_id,work_key) DO UPDATE SET required=true,updated_at=clock_timestamp();END IF;
  END LOOP;
  IF 'Parts'=ANY(ARRAY(SELECT jsonb_array_elements_text(item->'required_work'))) THEN INSERT INTO public.vehicle_work_items(vehicle_id,work_key,required,completed,updated_at) VALUES(vid,'PARTS',true,false,clock_timestamp()) ON CONFLICT(vehicle_id,work_key) DO UPDATE SET required=true,updated_at=clock_timestamp();END IF;
  INSERT INTO public.pdc_exact_email_import_receipts_501(provider_uid,parent_source_hash,attachment_hash,stock_number,job_card_number,vehicle_id,canonical_import_receipt_id,operation_count,source_manifest,authorized_by,authorized_by_email,production_untouched) VALUES('1:'||(item->>'uid'),item->>'source_hash',item->>'attachment_hash',item->>'stock',item->>'job_card',vid,rec.receipt_id,n,item,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au',true);
  SELECT count(*) INTO c1 FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=vid;SELECT count(*) INTO c2 FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id=vid AND active AND source_operation_line_id IS NOT NULL;SELECT jsonb_array_length(public.pdc_qc_operation_lines_379(vid)) INTO c3;IF c1<>n OR c2<>n OR c3<>n THEN RAISE EXCEPTION 'PDC_501_OPERATION_PARITY_FAILED:% source=% adjustments=% qc=% expected=%',item->>'stock',c1,c2,c3,n;END IF;
 END LOOP;
 UPDATE public.pdc_email_vehicle_revision SET revision=revision+1,updated_at=clock_timestamp() WHERE singleton;
