UPDATE public.pdc_email_monitor_pilot SET enabled=false,automatic_rule_application=false,automatic_authenticated_jobcards=false,outbound_email_enabled=false,updated_at=clock_timestamp() WHERE singleton;UPDATE public.monitored_mailboxes SET active=false,updated_at=clock_timestamp() WHERE mailbox_key='pdc_pmb_email';UPDATE public.pdc_monitor_stage_activation_writers SET active=false,revoked_at=clock_timestamp(),reason='Exact UID639/640 imports complete; writer contained' WHERE active AND revoked_at IS NULL;UPDATE public.pdc_email_monitor_status SET running_status='stopped',last_successful_run=clock_timestamp(),last_finished_at=clock_timestamp(),last_error=NULL,last_error_code=NULL,updated_at=clock_timestamp() WHERE singleton;
DO $p$ BEGIN IF (SELECT count(*) FROM public.pdc_exact_email_import_receipts_501)<>2 OR (SELECT sum(operation_count) FROM public.pdc_exact_email_import_receipts_501)<>37 OR (SELECT count(*) FROM public.vehicles WHERE deleted_at IS NULL AND stock_number_normalized IN('13000769','13017855'))<>2 OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards) OR EXISTS(SELECT 1 FROM public.monitored_mailboxes WHERE active) OR EXISTS(SELECT 1 FROM public.pdc_monitor_stage_activation_writers WHERE active AND revoked_at IS NULL) THEN RAISE EXCEPTION 'PDC_501_IMPORT_OR_CONTAINMENT_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827051000','501_exact_uid639_640_all_operations_import',ARRAY['Import exact authenticated Gmail UID 639 Stock 13000769 and UID 640 Stock 13017855 from retained Job Card PDFs','Link each to one unique current Navision Stock row and refresh authoritative vehicle details and location','Retain and project every one of 37 numbered operations exactly once including explicit zero-hour lines; universal Pre Delivery is 1.50 hours and reflective safety striping routes to Sublet','Create no bookings and contain all automatic writers after the atomic cycle','Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
